  public static func add(ELAPSED_MS: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ELAPSED_MS, def: 0, at: VT.ELAPSED_MS) }
  public static func add(AS_OF_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: AS_OF_MS, def: 0, at: VT.AS_OF_MS) }
  public static func add(PROVIDER_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PROVIDER_ID, at: VT.PROVIDER_ID) }
  public static func add(SOURCE_NAME: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOURCE_NAME, at: VT.SOURCE_NAME) }
  public static func endAGR(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createAGR(
    _ fbb: inout FlatBufferBuilder,
    KIND: agrKind = .histogram,
    SCHEMA_NAMEOffset SCHEMA_NAME: Offset = Offset(),
    SQLOffset SQL: Offset = Offset(),
    X_FIELDOffset X_FIELD: Offset = Offset(),
    Y_FIELDSVectorOffset Y_FIELDS: Offset = Offset(),
    X_IS_TIME: Bool = false,
    X_UNITOffset X_UNIT: Offset = Offset(),
    BINSVectorOffset BINS: Offset = Offset(),
    CATEGORIESVectorOffset CATEGORIES: Offset = Offset(),
    SERIESVectorOffset SERIES: Offset = Offset(),
    PIVOTVectorOffset PIVOT: Offset = Offset(),
    ROW_KEYSVectorOffset ROW_KEYS: Offset = Offset(),
    COL_KEYSVectorOffset COL_KEYS: Offset = Offset(),
    SCANNED: UInt64 = 0,
    MATCHED: UInt64 = 0,
    STORED: UInt64 = 0,
    PARTIAL: Bool = false,
    TRUNCATED: Bool = false,
    ELAPSED_MS: UInt32 = 0,
    AS_OF_MS: Int64 = 0,
    PROVIDER_IDOffset PROVIDER_ID: Offset = Offset(),
    SOURCE_NAMEOffset SOURCE_NAME: Offset = Offset()
  ) -> Offset {
    let __start = AGR.startAGR(&fbb)
    AGR.add(KIND: KIND, &fbb)
    AGR.add(SCHEMA_NAME: SCHEMA_NAME, &fbb)
    AGR.add(SQL: SQL, &fbb)
    AGR.add(X_FIELD: X_FIELD, &fbb)
    AGR.addVectorOf(Y_FIELDS: Y_FIELDS, &fbb)
    AGR.add(X_IS_TIME: X_IS_TIME, &fbb)
    AGR.add(X_UNIT: X_UNIT, &fbb)
    AGR.addVectorOf(BINS: BINS, &fbb)
    AGR.addVectorOf(CATEGORIES: CATEGORIES, &fbb)
    AGR.addVectorOf(SERIES: SERIES, &fbb)
    AGR.addVectorOf(PIVOT: PIVOT, &fbb)
    AGR.addVectorOf(ROW_KEYS: ROW_KEYS, &fbb)
    AGR.addVectorOf(COL_KEYS: COL_KEYS, &fbb)
    AGR.add(SCANNED: SCANNED, &fbb)
    AGR.add(MATCHED: MATCHED, &fbb)
    AGR.add(STORED: STORED, &fbb)
    AGR.add(PARTIAL: PARTIAL, &fbb)
    AGR.add(TRUNCATED: TRUNCATED, &fbb)
    AGR.add(ELAPSED_MS: ELAPSED_MS, &fbb)
    AGR.add(AS_OF_MS: AS_OF_MS, &fbb)
    AGR.add(PROVIDER_ID: PROVIDER_ID, &fbb)
    AGR.add(SOURCE_NAME: SOURCE_NAME, &fbb)
    return AGR.endAGR(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.KIND, fieldName: "KIND", required: false, type: agrKind.self)
    try _v.visit(field: VT.SCHEMA_NAME, fieldName: "SCHEMA_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SQL, fieldName: "SQL", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.X_FIELD, fieldName: "X_FIELD", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.Y_FIELDS, fieldName: "Y_FIELDS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.X_IS_TIME, fieldName: "X_IS_TIME", required: false, type: Bool.self)
    try _v.visit(field: VT.X_UNIT, fieldName: "X_UNIT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.BINS, fieldName: "BINS", required: false, type: ForwardOffset<Vector<ForwardOffset<AGRBin>, AGRBin>>.self)
    try _v.visit(field: VT.CATEGORIES, fieldName: "CATEGORIES", required: false, type: ForwardOffset<Vector<ForwardOffset<AGRCategory>, AGRCategory>>.self)
    try _v.visit(field: VT.SERIES, fieldName: "SERIES", required: false, type: ForwardOffset<Vector<ForwardOffset<AGRSeries>, AGRSeries>>.self)
    try _v.visit(field: VT.PIVOT, fieldName: "PIVOT", required: false, type: ForwardOffset<Vector<ForwardOffset<AGRPivotCell>, AGRPivotCell>>.self)
    try _v.visit(field: VT.ROW_KEYS, fieldName: "ROW_KEYS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.COL_KEYS, fieldName: "COL_KEYS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.SCANNED, fieldName: "SCANNED", required: false, type: UInt64.self)
    try _v.visit(field: VT.MATCHED, fieldName: "MATCHED", required: false, type: UInt64.self)
    try _v.visit(field: VT.STORED, fieldName: "STORED", required: false, type: UInt64.self)
    try _v.visit(field: VT.PARTIAL, fieldName: "PARTIAL", required: false, type: Bool.self)
    try _v.visit(field: VT.TRUNCATED, fieldName: "TRUNCATED", required: false, type: Bool.self)
    try _v.visit(field: VT.ELAPSED_MS, fieldName: "ELAPSED_MS", required: false, type: UInt32.self)
    try _v.visit(field: VT.AS_OF_MS, fieldName: "AS_OF_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.PROVIDER_ID, fieldName: "PROVIDER_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SOURCE_NAME, fieldName: "SOURCE_NAME", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
}
